export function pages<T>(items: ReadonlyArray<T>, size: number): Array<Array<T>> {
	const count = Math.ceil(items.length / size)
	const result: Array<Array<T>> = []

	for (let index = 0; index <= count; index += 1) {
		result.push(items.slice(index * size, (index + 1) * size))
	}

	return result
}

